INSERT INTO programs (code, name, department) VALUES
    ('BSCpE', 'BS Computer Engineering', 'College of Engineering'),
    ('BSECE', 'BS Electronics Engineering', 'College of Engineering'),
    ('BSCS', 'BS Computer Science', 'College of Computer Studies'),
    ('BSIT', 'BS Information Technology', 'College of Computer Studies');
INSERT INTO courses (course_code, title, units, description) VALUES
    ('CPE 201', 'Data Structures and Algorithms', 3, 'Linear and non-linear data structures, sorting, searching and complexity analysis.'),
    ('CPE 301', 'Microprocessors and Microcontrollers', 3, 'Architecture, assembly programming and interfacing of microprocessor-based systems.'),
    ('CPE 312', 'Computer Networks and Security', 3, 'OSI/TCP-IP models, routing, switching and fundamentals of network security.'),
    ('CPE 321', 'Operating Systems', 3, 'Processes, threads, scheduling, memory management and file systems.'),
    ('CPE 401', 'Embedded Systems Design', 3, 'Design of real-time embedded systems using sensors, actuators and RTOS concepts.'),
    ('CS 211', 'Object-Oriented Programming', 3, 'Classes, inheritance, polymorphism and design principles using Java.'),
    ('CS 221', 'Database Management Systems', 3, 'Relational model, SQL, normalization, transactions and indexing.'),
    ('IT 231', 'Web Systems and Technologies', 3, 'Client-server web development with HTML, CSS, JavaScript and REST APIs.'),
    ('MATH 201', 'Differential Equations', 3, 'First- and higher-order ordinary differential equations and applications.'),
    ('ECE 211', 'Electronic Circuits and Devices', 4, 'Diodes, transistors, amplifiers and basic analog circuit analysis (with laboratory).');
